  "inlineSchema": "generator client {\n  provider      = \"prisma-client-js\"\n  binaryTargets = [\"native\", \"windows\", \"debian-openssl-3.0.x\"]\n}\n\ndatasource db {\n  provider = \"mongodb\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// -------------------------------------------------------------\n// 1. ROLES (Permisos y Perfiles del Sistema)\n// -------------------------------------------------------------\nmodel Role {\n  id          String   @id @default(auto()) @map(\"_id\") @db.ObjectId\n  name        String   @unique // \"ADMIN\", \"USER\", \"MODERATOR\"\n  description String?\n  isActive    Boolean  @default(true)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  // Relaciones\n  users User[]\n\n  @@map(\"roles\")\n}\n\n// -------------------------------------------------------------\n// 2. USUARIOS (Compradores, Vendedores y Administradores)\n// -------------------------------------------------------------\nmodel User {\n  id        String   @id @default(auto()) @map(\"_id\") @db.ObjectId\n  username  String   @unique\n  email     String   @unique\n  password  String\n  avatarUrl String?\n  bio       String?\n  city      String?\n  country   String   @default(\"España\")\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Clave foránea Role\n  roleId String @db.ObjectId\n\n  // Relaciones\n  role     Role      @relation(fields: [roleId], references: [id])\n  products Product[] @relation(\"SellerProducts\")\n\n  @@map(\"users\")\n}\n\n// -------------------------------------------------------------\n// 3. CATEGORÍAS (Jerarquía con autorreferencia)\n// -------------------------------------------------------------\nmodel Category {\n  id        String   @id @default(auto()) @map(\"_id\") @db.ObjectId\n  name      String\n  slug      String   @unique\n  parentId  String?  @db.ObjectId\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relación reflexiva para subcategorías\n  parent   Category?  @relation(\"CategoryHierarchy\", fields: [parentId], references: [id], onDelete: NoAction, onUpdate: NoAction)\n  children Category[] @relation(\"CategoryHierarchy\")\n\n  // Relación con productos\n  products Product[]\n\n  @@map(\"categories\")\n}\n\n// -------------------------------------------------------------\n// 4. MARCAS\n// -------------------------------------------------------------\nmodel Brand {\n  id        String   @id @default(auto()) @map(\"_id\") @db.ObjectId\n  name      String   @unique\n  slug      String   @unique\n  logoUrl   String?\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relación con productos\n  products Product[]\n\n  @@map(\"brands\")\n}\n\n// -------------------------------------------------------------\n// 5. PRODUCTOS (Entidad Base / Catálogo Padre)\n// -------------------------------------------------------------\nmodel Product {\n  id          String    @id @default(auto()) @map(\"_id\") @db.ObjectId\n  title       String\n  slug        String    @unique\n  description String\n  status      String    @default(\"available\") // \"available\" | \"reserved\" | \"sold\" | \"hidden\"\n  viewsCount  Int       @default(0)\n  isActive    Boolean   @default(true)\n  deletedAt   DateTime?\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  // Claves foráneas\n  sellerId   String @db.ObjectId\n  categoryId String @db.ObjectId\n  brandId    String @db.ObjectId\n\n  // Relaciones\n  seller   User             @relation(\"SellerProducts\", fields: [sellerId], references: [id])\n  category Category         @relation(fields: [categoryId], references: [id])\n  brand    Brand            @relation(fields: [brandId], references: [id])\n  variants ProductVariant[]\n\n  @@index([status, isActive, createdAt(sort: Desc)])\n  @@map(\"products\")\n}\n\n// -------------------------------------------------------------\n// 6. VARIANTES DE PRODUCTO (Tallas, Colores, Estado y Precios)\n// -------------------------------------------------------------\nmodel ProductVariant {\n  id        String   @id @default(auto()) @map(\"_id\") @db.ObjectId\n  sku       String?  @unique\n  size      String // \"XS\", \"S\", \"M\", \"L\", \"XL\", \"42\", etc.\n  color     String? // \"Negro\", \"Azul denim\", etc.\n  condition String // \"Nuevo con etiquetas\", \"Muy bueno\", etc.\n  price     Float\n  stock     Int      @default(1) // En segunda mano suele ser 1\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Clave foránea a Product\n  productId String @db.ObjectId\n\n  // Relaciones\n  product Product        @relation(fields: [productId], references: [id], onDelete: Cascade)\n  images  ProductImage[]\n\n  @@index([productId, size])\n  @@map(\"product_variants\")\n}\n\n// -------------------------------------------------------------\n// 7. IMÁGENES DE PRODUCTO (Colección Independiente)\n// -------------------------------------------------------------\nmodel ProductImage {\n  id        String   @id @default(auto()) @map(\"_id\") @db.ObjectId\n  url       String\n  altText   String?\n  isCover   Boolean  @default(false) // Indica si es la foto principal\n  sortOrder Int      @default(0)\n  createdAt DateTime @default(now())\n\n  // Polimorfismo / Identificación de entidad (ej: \"PRODUCT_VARIANT\", \"USER\", etc.)\n  entityType String? // Tipo de entidad asociada\n  entityId   String? @db.ObjectId // ID de la entidad asociada\n\n  // Clave foránea a Variante\n  variantId String @db.ObjectId\n\n  // Relaciones\n  variant ProductVariant @relation(fields: [variantId], references: [id], onDelete: Cascade)\n\n  @@index([variantId, sortOrder])\n  @@index([entityType, entityId])\n  @@map(\"product_images\")\n}\n",
